args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX schema: <http://schema.org/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?person ?label (COALESCE(?bd, ?bd2, ?bd3, ?bd4) AS ?birthDate) WHERE {
  ?person rdfs:label ?label .
  FILTER(langMatches(lang(?label), "EN")) .
  FILTER(?label IN ("Mickey Hart"@en, "Tony Owen"@en)) .
  OPTIONAL { ?person dbo:birthDate ?bd . }
  OPTIONAL { ?person dbp:birthDate ?bd2 . }
  OPTIONAL { ?person dbp:born ?bd3 . }
  OPTIONAL { ?person schema:birthDate ?bd4 . }
}
ORDER BY DESC(?birthDate)
LIMIT 10

